import java.util.*;

record RunState(String status, String owner) {}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Map<String, RunState> runs = new LinkedHashMap<>();
        for (int i = 0; i < n; i++) {
            String command = sc.next();
            String job = sc.next(), date = sc.next(), worker = sc.next();
            String key = job + "@" + date;
            RunState current = runs.get(key);
            if (command.equals("START")) {
                if (current == null || current.status().equals("FAILED")) {
                    runs.put(key, new RunState("RUNNING", worker));
                    System.out.println("STARTED " + key + " " + worker);
                } else if (current.status().equals("RUNNING")) {
                    System.out.println("BUSY " + key + " " + current.owner());
                } else {
                    System.out.println("ALREADY_DONE " + key);
                }
            } else {
                String outcome = sc.next();
                if (current != null && current.status().equals("RUNNING")
                        && current.owner().equals(worker)) {
                    String next = outcome.equals("SUCCESS") ? "DONE" : "FAILED";
                    runs.put(key, new RunState(next, worker));
                    System.out.println("FINISHED " + key + " " + next);
                } else {
                    System.out.println("REJECTED " + key);
                }
            }
        }
        int running = 0, done = 0, failed = 0;
        for (RunState state : runs.values()) {
            if (state.status().equals("RUNNING")) running++;
            else if (state.status().equals("DONE")) done++;
            else failed++;
        }
        System.out.println("SUMMARY running=" + running + " done=" + done + " failed=" + failed);
    }
}

