import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Set<Long> sorted = new TreeSet<>();
        for (int i = 0; i < n; i++) sorted.add(sc.nextLong());
        long checkpoint = sc.nextLong();
        int chunkSize = sc.nextInt();
        List<String> chunk = new ArrayList<>();
        long nextCheckpoint = checkpoint;
        for (long id : sorted) {
            if (id <= checkpoint) continue;
            chunk.add(String.valueOf(id));
            nextCheckpoint = id;
            if (chunk.size() == chunkSize) {
                System.out.println("CHUNK " + String.join(",", chunk));
                chunk.clear();
            }
        }
        if (!chunk.isEmpty()) System.out.println("CHUNK " + String.join(",", chunk));
        System.out.println("CHECKPOINT " + nextCheckpoint);
    }
}

