import java.util.*;

record Item(long id, String outcome) {}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long checkpoint = sc.nextLong();
        int d = sc.nextInt();
        Set<Long> done = new HashSet<>();
        for (int i = 0; i < d; i++) done.add(sc.nextLong());
        int n = sc.nextInt();
        List<Item> chunk = new ArrayList<>();
        for (int i = 0; i < n; i++) chunk.add(new Item(sc.nextLong(), sc.next()));

        boolean failed = false;
        for (Item item : chunk) {
            if (item.outcome().equals("fail")) failed = true;
        }
        int effects = 0;
        if (!failed) {
            for (Item item : chunk) {
                if (done.add(item.id())) effects++;
                checkpoint = Math.max(checkpoint, item.id());
            }
        }
        System.out.println("RESULT " + (failed ? "ROLLBACK" : "COMMIT"));
        System.out.println("CHECKPOINT " + checkpoint);
        System.out.println("EFFECTS " + effects);
        System.out.println("DONE " + done.size());
    }
}
